def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the palette strip (the row with the most distinct nonzero colors).
    strip_r = max(range(h), key=lambda r: len(set(x for x in grid[r] if x)))
    palette = [x for x in grid[strip_r] if x]

    # Find the color-1 shape component, excluding the palette strip.
    points = {(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == 1 and r != strip_r}
    components = []
    while points:
        seed = points.pop()
        comp = {seed}
        todo = [seed]
        while todo:
            r, c = todo.pop()
            for q in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                if q in points:
                    points.remove(q)
                    comp.add(q)
                    todo.append(q)
        components.append(comp)

    shape = max(components, key=len)
    top = min(r for r, c in shape)
    bottom = max(r for r, c in shape)
    left = min(c for r, c in shape)
    mask = {(r-top, c-left) for r, c in shape}
    tile_h = bottom - top + 1

    start = top - palette.index(1) * tile_h
    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        for dr, dc in mask:
            r, c = start + i * tile_h + dr, left + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
    return out
